{
  "geracao_sequencia_aleatoria": {
    "julgamento": "Low",
    "justificativa": "O estudo relata que a randomização foi realizada por um sistema centralizado e seguro baseado na web (Agencia Laín Entralgo), o que indica um processo aleatório adequado."
  },
  "ocultacao_alocacao": {
    "julgamento": "Low",
    "justificativa": "A ocultação da alocação foi garantida por envelopes opacos, lacrados e sequencialmente numerados, abertos apenas no dia da cirurgia."
  },
  "cegamento_participantes_equipe": {
    "julgamento": "High",
    "justificativa": "O artigo reconhece explicitamente que foi impossível cegar os pesquisadores que realizaram o monitoramento hemodinâmico, uma vez que o grupo de intervenção recebia um protocolo diferente de administração de fluidos e medicamentos."
  },
  "cegamento_avaliadores_desfecho": {
    "julgamento": "Low",
    "justificativa": "Os sujeitos e os médicos que coletaram dados e avaliaram os pacientes no pós-operatório estavam cegos quanto à alocação do tratamento, conforme descrito no método."
  },
  "dados_desfecho_incompletos": {
    "julgamento": "Low",
    "justificativa": "O estudo relata que não houve pacientes perdidos para o follow-up e que a análise foi realizada em uma base de intenção de tratar modificada, incluindo todos os randomizados que receberam o tratamento."
  },
  "relato_seletivo": {
    "julgamento": "Low",
    "justificativa": "O artigo declara que foi realizado e reportado de acordo com as diretrizes CONSORT, e os desfechos primários e secundários pré-definidos foram reportados nos resultados."
  },
  "outros_vieses": {
    "julgamento": "Unclear",
    "justificativa": "O artigo não fornece informações suficientes sobre o controle de fatores de confusão, como o status de ASA (que foi significativamente diferente entre os grupos na análise basal reportada na Tabela 1) ou a implementação de protocolos ERAS, que poderiam influenciar os resultados de forma não controlada."
  },
  "risco_global": {
    "julgamento": "High",
    "justificativa": "O risco de viés global é alto devido à impossibilidade de cegar a equipe de anestesia (desceber bias/performance bias) e à diferença significativa reportada nas características basais (ASA) entre os grupos, sem evidência clara de ajuste estatístico robusto para isso nos resultados principais."
  }
}
